// ── Live complexity demonstrations ──────────────────────────────

// O(1) — constant, no matter how large arr is
function first(arr) { return arr[0]; }

// O(log n) — binary search, input halves each iteration
function binarySearch(arr, target) {
  let lo = 0, hi = arr.length - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (arr[mid] === target) return mid;
    if (arr[mid] < target) lo = mid + 1;
    else hi = mid - 1;
  }
  return -1;
}
console.log(binarySearch([1,3,5,7,9,11], 7)); // 3

// O(n) — single loop
function sumArray(arr) { return arr.reduce((a, b) => a + b, 0); }

// O(n log n) — merge sort
function mergeSort(arr) {
  if (arr.length <= 1) return arr;
  const mid = arr.length >> 1;
  const L = mergeSort(arr.slice(0, mid));
  const R = mergeSort(arr.slice(mid));
  const out = [];
  let i = 0, j = 0;
  while (i < L.length && j < R.length)
    out.push(L[i] <= R[j] ? L[i++] : R[j++]);
  return out.concat(L.slice(i)).concat(R.slice(j));
}
console.log(mergeSort([5, 2, 8, 1, 9, 3])); // [1,2,3,5,8,9]

// O(n²) — nested loop, all pairs
function allPairs(arr) {
  const pairs = [];
  for (let i = 0; i < arr.length; i++)
    for (let j = i + 1; j < arr.length; j++)
      pairs.push([arr[i], arr[j]]);
  return pairs;
}
console.log(allPairs([1,2,3]).length); // 3 pairs = C(3,2)

// O(2^n) — naive Fibonacci (exponential, avoid!)
function fib(n) { return n <= 1 ? n : fib(n-1) + fib(n-2); }
// O(n) memoised version:
function fibMemo(n, memo = {}) {
  if (n <= 1) return n;
  if (memo[n] !== undefined) return memo[n];
  return memo[n] = fibMemo(n-1, memo) + fibMemo(n-2, memo);
}
console.log(fibMemo(40)); // 102334155, instant

// ── Space complexity: hidden costs ──────────────────────────────

// O(1) space — in-place two-pointer reverse
function reverseInPlace(arr) {
  let l = 0, r = arr.length - 1;
  while (l < r) { [arr[l], arr[r]] = [arr[r], arr[l]]; l++; r--; }
  return arr;
}

// O(n) space — new array (not in-place)
function reverseNew(arr) { return [...arr].reverse(); }

// O(n) space — call stack in recursion (often overlooked!)
function sumRecursive(arr, i = 0) {
  if (i === arr.length) return 0;
  return arr[i] + sumRecursive(arr, i + 1); // n frames on the call stack
}

// O(log n) space — merge sort call stack depth is log n
// (even though output array costs O(n), the STACK depth is O(log n))

// ── Hash map: O(n) time from O(n²) brute force ──────────────────
// Find duplicates: O(n²) brute force
function hasDupBrute(arr) {
  for (let i = 0; i < arr.length; i++)
    for (let j = i+1; j < arr.length; j++)
      if (arr[i] === arr[j]) return true;
  return false;
}
// O(n) with a Set
function hasDupFast(arr) {
  const seen = new Set();
  for (const x of arr) {
    if (seen.has(x)) return true;
    seen.add(x);
  }
  return false;
}
console.log(hasDupFast([1, 2, 3, 2])); // true
// Trade: O(n) time, O(n) space — the classic time-space trade-off.
